        attrs1.add("key1", "value1");

        Attributes attrs2 = new Attributes();
        attrs2.add("key2", "value2");

        attrs1.addAll(attrs2);
        Assert.assertTrue(attrs1.hasKey("key1") && attrs1.hasKey("key2"));
    }

